    pub fn DrawRect(self: *GraphicsBase, rp: *graphics.RastPort, area: *const graphics.Rect) void {
        return libraries.call(self, LVO.DrawRect, Fn.DrawRect, .{ rp, area });
    }

    /// A circle's outline about (cx, cy).
    pub fn DrawCircle(self: *GraphicsBase, rp: *graphics.RastPort, cx: i32, cy: i32, radius: i32) void {
        return libraries.call(self, LVO.DrawCircle, Fn.DrawCircle, .{ rp, cx, cy, radius });
    }

    /// An ellipse's outline about (cx, cy), `rx` wide and `ry` tall.
    pub fn DrawEllipse(self: *GraphicsBase, rp: *graphics.RastPort, cx: i32, cy: i32, rx: i32, ry: i32) void {
        return libraries.call(self, LVO.DrawEllipse, Fn.DrawEllipse, .{ rp, cx, cy, rx, ry });
    }

    /// Part of a circle's outline, from `from` degrees to `to` degrees the way
    /// the numbers increase, with 0 to the right and 90 upward.
    pub fn DrawArc(self: *GraphicsBase, rp: *graphics.RastPort, cx: i32, cy: i32, radius: i32, from: i32, to: i32) void {
        return libraries.call(self, LVO.DrawArc, Fn.DrawArc, .{ rp, cx, cy, radius, from, to });
    }

    /// A line from the current point through each of `points` in turn, which
    /// then ends at the last of them. A closed shape repeats its first point.
    pub fn DrawPoly(self: *GraphicsBase, rp: *graphics.RastPort, count: u32, points: [*]const graphics.Point) void {
        return libraries.call(self, LVO.DrawPoly, Fn.DrawPoly, .{ rp, count, points });
    }

    /// Room to collect a filled shape in, for the Area calls: as many corners
    /// as will be needed, curves included. 0 gives the room back. False if
    /// there was no memory. The room goes with the RastPort.
    pub fn InitArea(self: *GraphicsBase, rp: *graphics.RastPort, max_points: u32) bool {
        return libraries.call(self, LVO.InitArea, Fn.InitArea, .{ rp, max_points });
    }

    /// Begin a shape at (x, y). A shape already begun is left to be filled
    /// with this one, so several shapes can be filled at once - one inside
    /// another is a hole.
    pub fn AreaMove(self: *GraphicsBase, rp: *graphics.RastPort, x: i32, y: i32) bool {
        return libraries.call(self, LVO.AreaMove, Fn.AreaMove, .{ rp, x, y });
    }

    /// The next corner of the shape being collected.
    pub fn AreaDraw(self: *GraphicsBase, rp: *graphics.RastPort, x: i32, y: i32) bool {
        return libraries.call(self, LVO.AreaDraw, Fn.AreaDraw, .{ rp, x, y });
    }

    /// A whole ellipse as a shape of its own.
    pub fn AreaEllipse(self: *GraphicsBase, rp: *graphics.RastPort, cx: i32, cy: i32, rx: i32, ry: i32) bool {
        return libraries.call(self, LVO.AreaEllipse, Fn.AreaEllipse, .{ rp, cx, cy, rx, ry });
    }

    /// A whole circle as a shape of its own.
    pub fn AreaCircle(self: *GraphicsBase, rp: *graphics.RastPort, cx: i32, cy: i32, radius: i32) bool {
        return libraries.call(self, LVO.AreaCircle, Fn.AreaCircle, .{ rp, cx, cy, radius });
    }

    /// A wedge: out from the middle, round the arc from `from` to `to`
