    pub fn AreaArc(self: *GraphicsBase, rp: *graphics.RastPort, cx: i32, cy: i32, radius: i32, from: i32, to: i32) bool {
        return libraries.call(self, LVO.AreaArc, Fn.AreaArc, .{ rp, cx, cy, radius, from, to });
    }

    /// Fill everything collected and begin again. Nothing collected fills
