    pub fn AreaEnd(self: *GraphicsBase, rp: *graphics.RastPort) bool {
        return libraries.call(self, LVO.AreaEnd, Fn.AreaEnd, .{rp});
    }

    /// A font of that name and height, or null if there is none. The fonts in
