    /// this is the move itself. Both must be in one format; overlapping is
    /// safe. An RtgBitMap is a Surface by pointer.
    pub fn BltBitMap(self: *GraphicsBase, src: *const rtg.Surface, src_x: i32, src_y: i32, dest: *rtg.Surface, dest_x: i32, dest_y: i32, width: i32, height: i32) i32 {
        return libraries.call(self, LVO.BltBitMap, Fn.BltBitMap, .{ src, src_x, src_y, dest, dest_x, dest_y, width, height });
    }

    /// The same, landing in a RastPort - so the destination's clip and draw
    /// mode apply and the rows are handed on. The source is a surface because
    /// the source of a blit has no drawing state.
    pub fn BltBitMapRastPort(self: *GraphicsBase, src: *const rtg.Surface, src_x: i32, src_y: i32, dest: *graphics.RastPort, dest_x: i32, dest_y: i32, width: i32, height: i32) void {
        return libraries.call(self, LVO.BltBitMapRastPort, Fn.BltBitMapRastPort, .{ src, src_x, src_y, dest, dest_x, dest_y, width, height });
    }

    /// The same again, leaving alone the pixels whose mask bit is clear. The
    /// mask is one bit to a pixel, rows of `mask_pitch` bytes, read from the
    /// source's corner.
    pub fn BltMaskBitMapRastPort(self: *GraphicsBase, src: *const rtg.Surface, src_x: i32, src_y: i32, dest: *graphics.RastPort, dest_x: i32, dest_y: i32, width: i32, height: i32, mask: [*]const u8, mask_pitch: u32) void {
        return libraries.call(self, LVO.BltMaskBitMapRastPort, Fn.BltMaskBitMapRastPort, .{ src, src_x, src_y, dest, dest_x, dest_y, width, height, mask, mask_pitch });
    }

    /// Stretch a rectangle of a surface to fill a rectangle of a RastPort,
    /// taking the nearest pixel for each. Clipped and handed on like any
    /// drawing call.
    pub fn BitMapScale(self: *GraphicsBase, src: *const rtg.Surface, src_area: *const graphics.Rect, dest: *graphics.RastPort, dest_area: *const graphics.Rect) void {
        return libraries.call(self, LVO.BitMapScale, Fn.BitMapScale, .{ src, src_area, dest, dest_area });
    }

    /// How much room `count` characters would take, without drawing them.
    pub fn TextExtent(self: *GraphicsBase, rp: *graphics.RastPort, string: [*]const u8, count: u32, out: *graphics.TextExtent) void {
        return libraries.call(self, LVO.TextExtent, Fn.TextExtent, .{ rp, string, count, out });
    }

    /// How many characters fit in the room given, and how much room those
    /// take. `constraining` is a box to fit inside, or null; `width` and
    /// `height` override it when either is above 0. `direction` is
    /// TEXT_FORWARD, or TEXT_BACKWARD with `string` pointing at the last
    /// character. 0 when the font is taller than the room.
    pub fn TextFit(self: *GraphicsBase, rp: *graphics.RastPort, string: [*]const u8, count: u32, out: *graphics.TextExtent, constraining: ?*const graphics.TextExtent, direction: i32, width: i32, height: i32) u32 {
        return libraries.call(self, LVO.TextFit, Fn.TextFit, .{ rp, string, count, out, constraining, direction, width, height });
    }

    /// Put a font on the library's list, so OpenFont can find it. What
    /// something that loads a font from a file calls once it has built one.
    /// False if it is already there.
    pub fn AddFont(self: *GraphicsBase, font: *graphics.TextFont) bool {
        return libraries.call(self, LVO.AddFont, Fn.AddFont, .{font});
    }

    /// Take one off again. False while anything still has it open.
    pub fn RemFont(self: *GraphicsBase, font: *graphics.TextFont) bool {
        return libraries.call(self, LVO.RemFont, Fn.RemFont, .{font});
    }

    /// What a font is: its width, height, baseline, the styles it was drawn
    /// with, and where one character's ink lands relative to the point.
    pub fn FontExtent(self: *GraphicsBase, font: *graphics.TextFont, out: *graphics.FontExtent) void {
        return libraries.call(self, LVO.FontExtent, Fn.FontExtent, .{ font, out });
    }

    /// Which styles can still be asked for on the RastPort's font - the ones
    /// it was not already drawn with. 0 with no font.
    pub fn AskSoftStyle(self: *GraphicsBase, rp: *graphics.RastPort) u32 {
        return libraries.call(self, LVO.AskSoftStyle, Fn.AskSoftStyle, .{rp});
    }

    /// Set the styles to `style`, keeping only the bits `enable` allows and
    /// only those AskSoftStyle offers. Answers what the style became.
    pub fn SetSoftStyle(self: *GraphicsBase, rp: *graphics.RastPort, style: u32, enable: u32) u32 {
        return libraries.call(self, LVO.SetSoftStyle, Fn.SetSoftStyle, .{ rp, style, enable });
    }

    /// What a GERR_ code means, in words, for a program that wants to say so.
    /// A code it does not know is "unknown error"; it never answers null.
    pub fn GraphicsErrorText(self: *GraphicsBase, code: i32) [*:0]const u8 {
        return libraries.call(self, LVO.GraphicsErrorText, Fn.GraphicsErrorText, .{code});
    }

    /// An empty region. Null if there was no memory. Free it with
    /// DisposeRegion.
    pub fn NewRegion(self: *GraphicsBase) ?*graphics.Region {
        return libraries.call(self, LVO.NewRegion, Fn.NewRegion, .{});
    }

    /// Give a region back, with every rectangle in it. Null is allowed.
    pub fn DisposeRegion(self: *GraphicsBase, region: ?*graphics.Region) void {
        return libraries.call(self, LVO.DisposeRegion, Fn.DisposeRegion, .{region});
    }

    /// Make it empty again, keeping the region itself.
    pub fn ClearRegion(self: *GraphicsBase, region: *graphics.Region) void {
        return libraries.call(self, LVO.ClearRegion, Fn.ClearRegion, .{region});
    }

    /// Whether the point is inside.
    pub fn PointInRegion(self: *GraphicsBase, region: *graphics.Region, x: i32, y: i32) bool {
        return libraries.call(self, LVO.PointInRegion, Fn.PointInRegion, .{ region, x, y });
    }

    /// Move the whole region by (dx, dy).
    pub fn OffsetRegion(self: *GraphicsBase, region: *graphics.Region, dx: i32, dy: i32) void {
        return libraries.call(self, LVO.OffsetRegion, Fn.OffsetRegion, .{ region, dx, dy });
    }

    /// Add the rectangle to the region. False if there was no memory, and the
    /// region is then unchanged.
    pub fn OrRectRegion(self: *GraphicsBase, region: *graphics.Region, rect: *const graphics.Rect) bool {
        return libraries.call(self, LVO.OrRectRegion, Fn.OrRectRegion, .{ region, rect });
    }

    /// Cut the region down to what is also inside the rectangle. False if
    /// there was no memory.
    pub fn AndRectRegion(self: *GraphicsBase, region: *graphics.Region, rect: *const graphics.Rect) bool {
        return libraries.call(self, LVO.AndRectRegion, Fn.AndRectRegion, .{ region, rect });
    }

    /// Take the rectangle out of the region. False if there was no memory.
    pub fn ClearRectRegion(self: *GraphicsBase, region: *graphics.Region, rect: *const graphics.Rect) bool {
        return libraries.call(self, LVO.ClearRectRegion, Fn.ClearRectRegion, .{ region, rect });
    }

    /// Everything in the rectangle that is not in the region, and everything
    /// in the region that is not in the rectangle. False if there was no
    /// memory.
    pub fn XorRectRegion(self: *GraphicsBase, region: *graphics.Region, rect: *const graphics.Rect) bool {
        return libraries.call(self, LVO.XorRectRegion, Fn.XorRectRegion, .{ region, rect });
    }

    /// Add everything in `source` to `dest`. False if there was no memory.
    pub fn OrRegionRegion(self: *GraphicsBase, source: *const graphics.Region, dest: *graphics.Region) bool {
        return libraries.call(self, LVO.OrRegionRegion, Fn.OrRegionRegion, .{ source, dest });
    }

    /// Cut `dest` down to what is also in `source`. False if there was no
    /// memory.
    pub fn AndRegionRegion(self: *GraphicsBase, source: *const graphics.Region, dest: *graphics.Region) bool {
        return libraries.call(self, LVO.AndRegionRegion, Fn.AndRegionRegion, .{ source, dest });
    }

    /// Take everything in `source` out of `dest`. False if there was no
    /// memory.
    pub fn SubRegionRegion(self: *GraphicsBase, source: *const graphics.Region, dest: *graphics.Region) bool {
        return libraries.call(self, LVO.SubRegionRegion, Fn.SubRegionRegion, .{ source, dest });
    }

    /// What is in one of the two but not both. False if there was no memory.
    pub fn XorRegionRegion(self: *GraphicsBase, source: *const graphics.Region, dest: *graphics.Region) bool {
        return libraries.call(self, LVO.XorRegionRegion, Fn.XorRegionRegion, .{ source, dest });
    }

    /// The rectangles a region is made of, which is how anything outside can
    /// see the shape of one. It answers how many there are and fills up to
    /// `max` of them, so a caller asks once with no room to find out how much
    /// it needs. They do not overlap and they are in order of min_y, then
    /// min_x. 0 means the region is empty.
    pub fn RegionRectangles(self: *GraphicsBase, region: *const graphics.Region, into: ?[*]graphics.Rect, max: u32) u32 {
        return libraries.call(self, LVO.RegionRectangles, Fn.RegionRectangles, .{ region, into, max });
    }

    /// Moves what is inside `area` of the RastPort itself: the contents go
    /// `dx` to the left and `dy` up, so a terminal scrolling its text up by a
    /// row asks for `dy` of one row. What the move vacates is left as it was -
    /// whoever scrolled is about to draw there. The pixels are read through
    /// the same clip the RastPort is drawn through, so a window moves its own
    /// pixels and not whatever is on the display at those coordinates. False
    /// when part of what was to be moved could not be read - a window covered
    /// by another keeps nothing of what is under it - and then nothing was
    /// moved at all, so the caller draws that area again.
    pub fn ScrollRaster(self: *GraphicsBase, rp: *graphics.RastPort, dx: i32, dy: i32, area: *const graphics.Rect) bool {
        return libraries.call(self, LVO.ScrollRaster, Fn.ScrollRaster, .{ rp, dx, dy, area });
    }

    /// Paints `area` of the RastPort the way an area with nothing in it yet is
    /// meant to look: through the hook `RPTAG_BackFill` names, or in the
    /// RastPort's own background pen when it names none, or not at all when it
    /// says `BACKFILL_NONE`.
    ///
    /// What that hook is, is set by whatever manages windows - it is what knows
    /// how a window's ground looks. This library only calls it, and learns
    /// nothing about windows or layers by doing so. A hook draws through this
    /// same RastPort, so what it puts down is clipped as anything else drawn
    /// through it would be.
    ///
    /// This is what an image erases with: a picture taken off a window leaves
    /// the window's own ground behind, pattern and all, rather than a flat
    /// rectangle of whichever pen happened to be set.
    pub fn EraseRect(self: *GraphicsBase, rp: *graphics.RastPort, area: *const graphics.Rect) void {
        return libraries.call(self, LVO.EraseRect, Fn.EraseRect, .{ rp, area });
    }

    /// A rectangle of pixels of one's own put down as they are, in any
    /// rtg.library format with colours (`format`, a PixelFormat) - converted to
    /// the surface's when the two differ, a row copied whole when they do not.
    /// `pixels` is rows of `pitch` bytes; (src_x, src_y) is where in them to
    /// start, and `area` where it lands, half-open. Clipped like any drawing;
    /// the pens and the draw mode are not used.
    pub fn WritePixelArray(self: *GraphicsBase, rp: *graphics.RastPort, pixels: [*]const u8, pitch: u32, format: u32, src_x: i32, src_y: i32, area: *const graphics.Rect) void {
        return libraries.call(self, LVO.WritePixelArray, Fn.WritePixelArray, .{ rp, pixels, pitch, format, src_x, src_y, area });
    }

    /// A rectangle of 8-bit colour numbers put down through `table`, 256 pens
    /// as 0xAARRGGBB: each byte is the pen at that place in it. Otherwise as
    /// WritePixelArray - the chunky picture of an old game, or a decoder's
    /// indexed frame, on a surface of any format.
    pub fn WriteLUTPixelArray(self: *GraphicsBase, rp: *graphics.RastPort, pixels: [*]const u8, pitch: u32, table: [*]const graphics.Pen, src_x: i32, src_y: i32, area: *const graphics.Rect) void {
        return libraries.call(self, LVO.WriteLUTPixelArray, Fn.WriteLUTPixelArray, .{ rp, pixels, pitch, table, src_x, src_y, area });
    }

    /// The drawing from here to the matching EndDraw is one piece of work:
    /// the rows it writes are gathered and handed to the display once, at
    /// the end, instead of after every call. What is drawn in two steps - a
    /// thing rubbed out and drawn again - is never shown half done.
    pub fn BeginDraw(self: *GraphicsBase, rp: *graphics.RastPort) void {
        return libraries.call(self, LVO.BeginDraw, Fn.BeginDraw, .{rp});
    }

    /// The end of that piece of work: the rows gathered since BeginDraw go
    /// to the display, in one. Nested BeginDraws need one of these each, and
    /// nothing goes until the last.
    pub fn EndDraw(self: *GraphicsBase, rp: *graphics.RastPort) void {
        return libraries.call(self, LVO.EndDraw, Fn.EndDraw, .{rp});
    }
};
